-- Jalankan SETELAH list_sppd_view_optimize.sql, dan SEBELUM deploy PengajuanController baru.
-- list_sppd_ringan = list_sppd tanpa perkiraan_total, uang_muka, rill_biaya, rill_tiket
-- (kolom tsb membuat MySQL menghitung ulang hitungan_biaya & realisasi_biaya untuk SEMUA SPPD).
-- Detail SPPD menghitung kolom tsb sendiri di PengajuanController::getDetail; list tidak memakainya.
-- Rollback: db/list_sppd_ringan_rollback.sql

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `list_sppd_ringan` AS
select `a`.`id` AS `id`,`a`.`nomor_sppd` AS `nomor_sppd`,`a`.`narasi_st` AS `narasi_st`,`a`.`nomor_dokumen` AS `nomor_dokumen`,`a`.`employe_id` AS `employe_id`,`a`.`nama` AS `nama`,`a`.`jabatan` AS `jabatan`,`a`.`submitted_by` AS `submitted_by`,`b`.`first_name` AS `first_name`,`a`.`golongan_rate` AS `golongan_rate`,`c`.`golongan` AS `golongan`,`c`.`id_pihak` AS `id_pihak`,`d`.`pihak_name` AS `pihak_name`,`a`.`ketetapan` AS `ketetapan`,`e`.`dasar_ketetapan` AS `dasar_ketetapan`,`a`.`created_at` AS `created_at`,`a`.`updated_at` AS `updated_at`,if(((select `ptpemaco_esign`.`verif_steps`.`status` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`type` = 'sign')) limit 1) = 'approve'),'signed',if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),'rejected','under_review')) AS `current_status`,if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`type` = 'check_document'))) > 0),if(((select `ptpemaco_esign`.`verif_steps`.`status` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`type` = 'verif_realisasi')) limit 1) = 'approve'),'verified',if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),'rejected','under_review')),NULL) AS `realisasi_status`,if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),NULL,(select `ptpemaco_esign`.`verif_steps`.`id_employe` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` is null)) order by `ptpemaco_esign`.`verif_steps`.`step` limit 1)) AS `current_reviewer`,(select `ptpemaco_esign`.`verif_steps`.`type` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` is null) and (`ptpemaco_esign`.`verif_steps`.`id_employe` = if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),NULL,(select `ptpemaco_esign`.`verif_steps`.`id_employe` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` is null)) order by `ptpemaco_esign`.`verif_steps`.`step` limit 1)))) limit 1) AS `current_type`,if(((select `proses`.`id` from `proses` where ((`proses`.`id_sppd` = `a`.`id`) and (`proses`.`as` = 'umum')) limit 1) is null),0,1) AS `by_umum`,if(((select `proses`.`id` from `proses` where ((`proses`.`id_sppd` = `a`.`id`) and (`proses`.`as` = 'uangmuka')) limit 1) is null),0,1) AS `uangmuka`,if(((select `proses`.`id` from `proses` where ((`proses`.`id_sppd` = `a`.`id`) and (`proses`.`as` = 'keuangan')) limit 1) is null),0,1) AS `by_keuangan`,(select `ts`.`waktu_berangkat` from `tujuan_sppds` `ts` where (`ts`.`id_sppd` = `a`.`id`) order by `ts`.`waktu_berangkat` limit 1) AS `mulai_tugas`,(select `ts`.`waktu_kembali` from `tujuan_sppds` `ts` where (`ts`.`id_sppd` = `a`.`id`) order by `ts`.`waktu_berangkat` desc limit 1) AS `selesai_tugas` from ((((`sppds` `a` join `ptpemaco_apam`.`employees` `b`) join `golongan_sppds` `c`) join `pihaks` `d`) join `ketetapan_sppds` `e`) where ((`a`.`submitted_by` = `b`.`employe_id`) and (`a`.`golongan_rate` = `c`.`id`) and (`c`.`id_pihak` = `d`.`id`) and (`a`.`ketetapan` = `e`.`id`));

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `approved_sppd` AS
select `b`.`id` AS `id_unique`,`b`.`id_employe` AS `approval_id`,`b`.`type` AS `type`,`ptpemaco_apam`.`c`.`first_name` AS `approval_name`,`b`.`status` AS `status`,`b`.`updated_at` AS `approved_at`,`a`.`id` AS `id`,`a`.`nomor_sppd` AS `nomor_sppd`,`a`.`nomor_dokumen` AS `nomor_dokumen`,`a`.`employe_id` AS `employe_id`,`a`.`nama` AS `nama`,`a`.`jabatan` AS `jabatan`,`a`.`submitted_by` AS `submitted_by`,`a`.`first_name` AS `first_name`,`a`.`golongan_rate` AS `golongan_rate`,`a`.`golongan` AS `golongan`,`a`.`id_pihak` AS `id_pihak`,`a`.`pihak_name` AS `pihak_name`,`a`.`ketetapan` AS `ketetapan`,`a`.`dasar_ketetapan` AS `dasar_ketetapan`,`a`.`created_at` AS `created_at`,`a`.`updated_at` AS `updated_at`,`a`.`current_status` AS `current_status`,`a`.`realisasi_status` AS `realisasi_status`,`a`.`current_reviewer` AS `current_reviewer`,`a`.`current_type` AS `current_type` from ((`list_sppd_ringan` `a` join `ptpemaco_esign`.`verif_steps` `b`) join `ptpemaco_apam`.`struktur_lengkap_oke` `c`) where ((`b`.`id_doc` = `a`.`nomor_dokumen`) and (`b`.`status` = 'approve') and (`b`.`id_employe` = `ptpemaco_apam`.`c`.`employe_id`)) order by `b`.`updated_at` desc;
